 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    small = []
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] == color:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            # Singleton and pair-sized components are stray marks; larger
            # components are part of the underlying colored shapes.
            if len(comp) <= 2:
                small.append(comp)
    for comp in small:
        cells = set(comp)
        votes = Counter()
        for r, c in comp:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
                    if (dr or dc) and 0 <= rr < h and 0 <= cc < w and (rr, cc) not in cells:
                        votes[grid[rr][cc]] += 1
        if votes:
            replacement = votes.most_common(1)[0][0]
            for r, c in comp:
                out[r][c] = replacement
    return out
"
